    $ch1Title = "समुद्र-मंथन, हलाहल विष और प्रदोष काल का महात्म्य";
    $ch1Story = "सत्ययुग की बात है। एक बार देवता और असुरों में शत्रुता बढ़ गई। असुरों के राजा बलि ने अपनी शक्ति से तीनों लोकों पर अधिकार कर लिया। देवता अपने राज्य से वंचित होकर इन्द्र के साथ ब्रह्माजी की शरण में पहुँचे। ब्रह्माजी ने उन्हें भगवान विष्णु के पास भेजा। भगवान विष्णु ने कहा —\n\n“देवताओ! असुरों से युद्ध करने की अपेक्षा उनसे मित्रता करके समुद्र-मंथन करो। इस मंथन से अमृत निकलेगा, जिसके पाने से तुम अमर हो जाओगे। परन्तु याद रखना — मंथन में विष भी निकलेगा। उसका सेवन भगवान शिव ही कर सकते हैं।”\n\nदेवताओं ने असुरों से सन्धि की और दोनों दल मिलकर समुद्र-मंथन करने लगे। मन्दराचल पर्वत को मथानी और वासुकि नाग को रस्सी बनाया गया। भगवान विष्णु ने कच्छप रूप धारण कर मन्दराचल को अपनी पीठ पर धारण किया। मंथन प्रारम्भ हुआ।\n\nसमुद्र-मंथन से पहले अनेक रत्न प्रकट हुए — कामधेनु, उच्चैःश्रवा घोड़ा, ऐरावत हाथी, कौस्तुभ मणि, पारिजात वृक्ष, अप्सराएँ, माँ लक्ष्मी और चन्द्रमा। अन्त में धन्वन्तरि अमृत कलश लेकर प्रकट हुए। परन्तु इसके पूर्व ही समुद्र-मंथन से एक भयंकर विष प्रकट हुआ — हलाहल।\n\nयह विष अत्यन्त भयंकर था। उसकी ज्वाला से सम्पूर्ण सृष्टि जलने लगी। देवता, असुर, मनुष्य, पशु-पक्षी, वृक्ष-वनस्पति — सभी व्याकुल हो उठे। विष की गर्मी से पृथ्वी तपने लगी, आकाश लाल हो गया और समुद्र उबलने लगा। प्राणियों के प्राण सूखने लगे।\n\nदेवता भगवान विष्णु के पास पहुँचे —\n\n“प्रभु! यह हलाहल विष सारी सृष्टि को भस्म कर रहा है। अब क्या करें?”\n\nभगवान विष्णु ने कहा —\n\n“देवताओ! यह विष केवल भगवान शिव ही पी सकते हैं। उन्हीं की शरण में जाओ।”\n\nसभी देवता और ऋषि-मुनि भगवान शिव के पास पहुँचे। उन्होंने हाथ जोड़कर प्रार्थना की —\n\n“ॐ नमः शिवाय। हे महादेव! हे कैलाशपति! आप ही हमारी रक्षा कर सकते हैं। यह हलाहल विष सारी सृष्टि को नष्ट कर रहा है। कृपया इसे अपने कण्ठ में धारण करें।”\n\nभगवान शिव ने करुणा से भरकर कहा —\n\n“देवताओ! तुम चिन्ता मत करो। मैं इस विष को ग्रहण करूँगा। परन्तु यह विष मेरे पेट में नहीं जाना चाहिए, अन्यथा सारी सृष्टि नष्ट हो जाएगी। मैं इसे अपने कण्ठ में ही रोकूँगा।”\n\nयह कहकर भगवान शिव ने हलाहल विष को अपनी अंजलि में लिया और पी लिया। विष उनके कण्ठ में ही रुक गया। उसके प्रभाव से उनका कण्ठ नीला पड़ गया। तभी से भगवान शिव नीलकण्ठ कहलाए।\n\nपरन्तु विष की गर्मी से भगवान शिव को असहनीय पीड़ा होने लगी। उनका शरीर तपने लगा। माँ पार्वती ने उनके कण्ठ को अपने हाथों से पकड़ लिया और कहा —\n\n“स्वामी! यह विष आपको पीड़ा दे रहा है। मैं इसे शान्त करने का उपाय करती हूँ।”\n\nमाँ पार्वती ने अपनी दिव्य शक्ति से विष की गर्मी को शान्त किया। उन्होंने भगवान शिव के कण्ठ पर जल छिड़का और उन्हें शीतलता प्रदान की।\n\nदेवताओं ने देखा कि भगवान शिव विष से व्याकुल हैं। उन्होंने सभी मिलकर भगवान शिव की स्तुति की —\n\n“ॐ नमः शिवाय। हे महादेव! आपने हमारी रक्षा के लिए यह विष पिया। आप धन्य हैं। अब आपकी पीड़ा शान्त हो।”\n\nउसी समय सूर्यदेव अस्त हो रहे थे। दिन और रात के संधिकाल में — जिसे प्रदोष काल कहा जाता है — भगवान शिव की पीड़ा चरम पर थी। देवता और ऋषि-मुनि उस प्रदोष काल में भगवान शिव की स्तुति करने लगे। उन्होंने जल, दूध, बेलपत्र और पुष्प अर्पित करके उनकी पूजा की।\n\nभगवान शिव उस प्रदोष काल की स्तुति से प्रसन्न हुए। उनकी पीड़ा शान्त होने लगी। उन्होंने देवताओं को आशीर्वाद दिया —\n\n“देवताओ! जिस प्रदोष काल में तुमने मेरी स्तुति की, वह काल मेरा प्रिय है। आज से जो भी भक्त प्रदोष काल में मेरी विधिपूर्वक पूजा करेगा, उसकी सभी पीड़ाएँ दूर होंगी और उसे मेरी विशेष कृपा प्राप्त होगी।”\n\nतभी से प्रदोष व्रत का प्रारम्भ हुआ। माँ पार्वती ने भगवान शिव से पूछा —\n\n“स्वामी! आपने विष पीकर सारी सृष्टि की रक्षा की। यह प्रदोष काल आपको इतना प्रिय क्यों है?”\n\nभगवान शिव ने मुस्कुराकर कहा —\n\n“देवि! प्रदोष काल वह समय है जब दिन और रात मिलते हैं। यह संधिकाल है — जहाँ स्थिरता और गति का संगम होता है। इस काल में की गई पूजा शीघ्र फल देती है। जिस प्रकार मैंने विष पीकर सृष्टि की रक्षा की, उसी प्रकार जो भक्त प्रदोष व्रत करके मेरी शरण में आता है, मैं उसके सारे कष्ट हर लेता हूँ।”\n\nमाँ पार्वती ने कहा —\n\n“स्वामी! तो प्रदोष व्रत की विधि क्या है? कृपया बताइए।”\n\nभगवान शिव ने कहा —\n\n“देवि! प्रदोष व्रत प्रत्येक मास की शुक्ल और कृष्ण त्रयोदशी को किया जाता है। सूर्यास्त से लेकर रात्रि के प्रथम प्रहर तक प्रदोष काल होता है। इस काल में मेरा पूजन सर्वश्रेष्ठ है। मैं तुम्हें विधि विस्तार से बताऊँगा।”\n\nपरन्तु उससे पहले भगवान शिव ने एक दिव्य दृष्टि से पृथ्वी की ओर देखा। उन्होंने कहा —\n\n“देवि! पृथ्वी पर एक भक्त है जो प्रदोष व्रत करने वाला है। उसकी कथा से यह व्रत का महात्म्य और भी स्पष्ट हो जाएगा। सुनो।”\n\nइस प्रकार समुद्र-मंथन, हलाहल विष और प्रदोष काल का महात्म्य स्थापित हुआ। अब भगवान शिव ने उस भक्त की कथा सुनानी आरम्भ की, जिसने प्रदोष व्रत से अपना जीवन धन्य किया।";

    $ch2Title = "धर्मदत्त की कथा — प्रदोष व्रत से पुत्र-प्राप्ति";
    $ch2Story = "भगवान शिव ने माँ पार्वती को एक दिव्य दृष्टि से पृथ्वी की ओर देखा और कहा —\n\n“देवि! पृथ्वी पर एक नगर है — प्रतिष्ठानपुर। वहाँ एक ब्राह्मण रहता था, जिसका नाम धर्मदत्त था। वह वेद-शास्त्रों का ज्ञाता, सत्यवादी और भगवान शिव का परम भक्त था। उसकी पत्नी का नाम सुशीला था। वे दोनों अत्यन्त धर्मात्मा थे, परन्तु सन्तान-सुख से वंचित थे। यह उनके जीवन का एकमात्र दुख था।”\n\nमाँ पार्वती ने पूछा —\n\n“स्वामी! धर्मदत्त ने अपनी सन्तान-प्राप्ति के लिए क्या किया?”\n\nभगवान शिव ने कहा —\n\n“देवि! सुनो, धर्मदत्त प्रतिदिन प्रातः स्नान करके भगवान शिव की पूजा करता। वह शिवलिंग पर जल, दूध, बेलपत्र और धतूरा अर्पित करता और हाथ जोड़कर प्रार्थना करता —\n\n‘ॐ नमः शिवाय। हे महादेव! हे करुणासागर! मैं आपकी शरण में हूँ। मेरे जीवन में सन्तान-सुख की कमी है। कृपया मुझे पुत्र-सुख प्रदान करें, जिससे मेरा वंश आगे बढ़े।’\n\nपरन्तु वर्षों तक प्रार्थना करने पर भी उन्हें सन्तान नहीं मिली। सुशीला भी माँ पार्वती की भक्त थी और प्रतिदिन पूजा करती। उसने भी माँ पार्वती से सन्तान की प्रार्थना की। परन्तु उनके भाग्य में अभी वह सुख लिखा नहीं था।”\n\nएक दिन धर्मदत्त अपने गाँव के शिव मंदिर में गए। वहाँ एक वृद्ध साधु बैठे थे, जो भगवान शिव के परम भक्त थे। धर्मदत्त ने उन्हें प्रणाम किया और अपना दुख सुनाया —\n\n“बाबा! मैं वर्षों से भगवान शिव की पूजा कर रहा हूँ, परन्तु मेरी सन्तान-प्राप्ति नहीं हो रही। क्या मेरी भक्ति में कोई कमी है? क्या मैंने कोई अपराध किया है?”\n\nसाधु ने उन्हें करुणा से देखा और कहा —\n\n“पुत्र! तुम्हारी भक्ति सच्ची है। परन्तु भगवान शिव को प्रसन्न करने का एक विशेष व्रत है, जिसे प्रदोष व्रत कहते हैं। यह व्रत त्रयोदशी के दिन सूर्यास्त से रात्रि के प्रथम प्रहर तक किया जाता है। इस काल में भगवान शिव की पूजा करने से सभी मनोकामनाएँ पूर्ण होती हैं। तुम इस व्रत को श्रद्धा से करो। भगवान शिव अवश्य प्रसन्न होंगे।”\n\nधर्मदत्त ने आश्चर्य से पूछा —\n\n“बाबा! यह प्रदोष व्रत कैसे किया जाता है? कृपया मुझे विधि बताइए।”\n\nसाधु ने कहा —\n\n“पुत्र! सुनो —\n\n1. संकल्प: त्रयोदशी के दिन प्रातः स्नान करके स्वच्छ वस्त्र पहनो। भगवान शिव के सम्मुख बैठकर हाथ में जल और अक्षत लेकर संकल्प करो कि ‘मैं आज प्रदोष व्रत करूँगा। मेरी मनोकामना पूर्ण हो।’\n2. व्रत: दिन में फलाहार या निराहार रहो। अस्वस्थता में चिकित्सकीय परामर्श का पालन करो।\n3. प्रदोष पूजन: सूर्यास्त के बाद, जब प्रदोष काल हो, तब शिवलिंग का विधिवत पूजन करो। जल, दूध, दही, घी, शहद, शर्करा से अभिषेक करो। बेलपत्र, धतूरा, शमी पत्र, कुशा, कनेर के फूल अर्पित करो। धूप, दीप जलाओ और शिव-आरती गाओ।\n4. कथा श्रवण: प्रदोष व्रत की कथा श्रद्धापूर्वक सुनो।\n5. रात्रि जागरण: रात्रि में शिव-नाम का जप करो और जागरण करो।\n6. पारण: अगले दिन स्नान करके पारण करो।”\n\nधर्मदत्त ने साधु को प्रणाम किया और घर लौटकर अपनी पत्नी सुशीला को सारी बात बताई। सुशीला ने प्रसन्न होकर कहा —\n\n“स्वामी! यह तो भगवान शिव की कृपा है। हमें यह व्रत अवश्य करना चाहिए।”\n\nउसी मास की त्रयोदशी आई। धर्मदत्त और सुशीला ने प्रातः स्नान किया और संकल्प लिया। दिनभर उन्होंने अन्न-जल ग्रहण नहीं किया। सायंकाल सूर्यास्त के बाद, जब प्रदोष काल आया, उन्होंने शिवलिंग का विधिवत पूजन किया। धर्मदत्त ने जल, दूध और पंचामृत से अभिषेक किया। सुशीला ने बेलपत्र, धतूरा और पुष्प अर्पित किए। दोनों ने मिलकर शिव-आरती गाई —\n\n“ॐ जय शिव ओंकारा, स्वामी जय शिव ओंकारा।\nब्रह्मा विष्णु सदाशिव, अर्द्धांगी धारा॥”\n\nपूजन के बाद उन्होंने प्रदोष व्रत की कथा सुनी। रात्रि में उन्होंने शिव-नाम का जप किया और जागरण किया। अगले दिन पारण किया।\n\nइस प्रकार धर्मदत्त और सुशीला ने प्रत्येक मास की त्रयोदशी को प्रदोष व्रत करना आरम्भ किया। छः मास बीत गए। उनकी भक्ति और व्रत से भगवान शिव प्रसन्न हो गए।\n\nएक रात्रि भगवान शिव ने धर्मदत्त को स्वप्न में दर्शन दिए। उन्होंने कहा —\n\n“धर्मदत्त! तुम्हारे प्रदोष व्रत और भक्ति से मैं प्रसन्न हूँ। तुम्हारी मनोकामना पूर्ण होगी। तुम्हें पुत्र-सुख प्राप्त होगा। परन्तु एक बात याद रखना — यह पुत्र तुम्हें मेरी कृपा से मिलेगा। उसका नाम ‘शिवदत्त’ रखना और उसे मेरा भक्त बनाना।”\n\nधर्मदत्त ने स्वप्न में हाथ जोड़कर कहा —\n\n“महादेव! मैं आपकी कृपा से धन्य हूँ। आपने मेरी प्रार्थना सुनी।”\n\nकुछ समय पश्चात सुशीला गर्भवती हुई। नौ मास पूर्ण होने पर उसने एक तेजस्वी बालक को जन्म दिया। बालक के मुख पर ऐसा तेज था मानो स्वयं भगवान शिव ने उसे आशीर्वाद दिया हो। धर्मदत्त ने उसका नाम शिवदत्त रखा।\n\nशिवदत्त बचपन से ही भगवान शिव का परम भक्त था। वह प्रतिदिन शिवलिंग का पूजन करता और ‘ॐ नमः शिवाय’ का जप करता। धर्मदत्त और सुशीला अपने पुत्र को देखकर धन्य हो गए। उन्होंने भगवान शिव को धन्यवाद दिया —\n\n“ॐ नमः शिवाय। हे महादेव! आपने हमारी सन्तान-प्राप्ति की इच्छा पूर्ण की। हम सदा आपके ऋणी रहेंगे।”\n\nधर्मदत्त ने प्रदोष व्रत को अपने जीवन का अभिन्न अंग बना लिया। वह प्रत्येक त्रयोदशी को व्रत करता और शिव-पूजन करता। उसके घर में सुख-शान्ति और समृद्धि बनी रहती।\n\nपरन्तु शिवदत्त के जीवन में भी एक परीक्षा आने वाली थी। जब वह सोलह वर्ष का हुआ, तो एक दिन वह वन में फूल चुनने गया। वहाँ उसने देखा कि एक भयंकर दैत्य एक कन्या को पकड़कर ले जा रहा है। कन्या चिल्ला रही थी —\n\n“बचाओ! बचाओ! कोई मेरी रक्षा करो!”\n\nशिवदत्त ने बिना विचार किए आगे बढ़कर कहा —\n\n“अरे दैत्य! यह निर्दोष कन्या कौन है? तुम इसे क्यों पकड़कर ले जा रहे हो?”\n\nदैत्य ने क्रोध से देखा —\n\n“ओ ब्राह्मण कुमार! यह कन्या मेरी पत्नी बनेगी। तू इसे बचाने की कोशिश मत कर। यदि तू आगे बढ़ा, तो मैं तुझे भी मार गिराऊँगा।”\n\nशिवदत्त ने कन्या को देखा। वह भयभीत थी और उसकी आँखों में आँसू थे। शिवदत्त ने साहस से कहा —\n\n“दैत्य! यदि तुम्हें युद्ध करना है, तो मुझसे करो। लेकिन इस कन्या को मत छूना।”\n\nदैत्य ने गरजकर अपना गदा उठाया और शिवदत्त पर प्रहार किया। शिवदत्त भगवान शिव का परम भक्त था। उसने मन में ‘ॐ नमः शिवाय’ का जप किया और अपनी लाठी से दैत्य का सामना किया। परन्तु दैत्य बहुत शक्तिशाली था। शिवदत्त कुछ ही क्षणों में थक गया।\n\nदैत्य ने जब उस पर प्रहार किया, तो शिवदत्त ने भगवान शिव को पुकारा —\n\n“हे महादेव! मेरी रक्षा करो!”\n\nउसी क्षण आकाश में एक दिव्य प्रकाश फैल गया। भगवान शिव अपने दिव्य रूप में प्रकट हुए। उनके हाथ में त्रिशूल था और मुख पर क्रोध की आभा थी। उन्होंने दैत्य को देखा और गम्भीर स्वर में कहा —\n\n“दुष्ट! यह बालक मेरा भक्त है। इसने प्रदोष व्रत से मुझे प्रसन्न किया है। तू इसकी हानि नहीं कर सकता।”\n\nदैत्य ने भगवान शिव को देखा और भय से काँपने लगा। उसने हाथ जोड़कर क्षमा माँगी —\n\n“महादेव! मैंने अज्ञानवश यह किया। मुझे क्षमा करें।”\n\nभगवान शिव ने कहा —\n\n“दैत्य! तू अपने मार्ग पर चला जा। और इस कन्या को छोड़ दे।”\n\nदैत्य ने कन्या को छोड़ दिया और वहाँ से भाग गया।\n\nभगवान शिव ने शिवदत्त को आशीर्वाद दिया —\n\n“शिवदत्त! तू धन्य है। तूने प्रदोष व्रत और भक्ति से मुझे प्रसन्न किया। तेरी रक्षा सदा मैं करूँगा।”\n\nयह कहकर भगवान शिव अन्तर्धान हो गए।\n\nकन्या ने शिवदत्त को प्रणाम किया और अपना परिचय दिया —\n\n“महात्मा! मेरा नाम सुमंगला है। मैं इस नगर के व्यापारी की कन्या हूँ। यह दैत्य मुझे पकड़कर ले जा रहा था। आपने मेरी रक्षा की। मैं आपकी ऋणी हूँ।”\n\nशिवदत्त ने कन्या को उसके घर छोड़ दिया। व्यापारी ने शिवदत्त को देखा और कहा —\n\n“पुत्र! तुमने मेरी कन्या की रक्षा की। यदि तुम चाहो तो मैं अपनी कन्या का विवाह तुमसे कर दूँ।”\n\nशिवदत्त ने कहा —\n\n“महाशय! यह मेरा सौभाग्य होगा। परन्तु मैं अपने माता-पिता की आज्ञा लेकर आता हूँ।”\n\nशिवदत्त ने घर लौटकर सारी बात अपने माता-पिता को सुनाई। धर्मदत्त और सुशीला ने प्रसन्न होकर कहा —\n\n“पुत्र! तुमने जो किया, वह धर्मयुक्त कार्य है। तुम्हारा विवाह हम करेंगे।”\n\nइस प्रकार शिवदत्त और सुमंगला का विवाह हो गया। दोनों ने मिलकर भगवान शिव की भक्ति की और प्रदोष व्रत करना जारी रखा। उनके घर में सदा सुख-शान्ति बनी रही।";

    $ch3Title = "शिवदत्त-सुमंगला की परीक्षा और प्रदोष व्रत का चमत्कार";
    $ch3Story = "विवाह के पश्चात शिवदत्त और सुमंगला अपने घर में सुखपूर्वक रहने लगे। शिवदत्त पिता धर्मदत्त के साथ यज्ञ-हवन करता, वेद-पाठ करता और प्रत्येक त्रयोदशी को प्रदोष व्रत रखता। सुमंगला भी अपने पति के साथ व्रत में सहयोग करती। उनके घर में माँ गौरी और भगवान शिव की कृपा से सुख-शान्ति थी।\n\nपरन्तु समय बीतने के साथ एक समस्या उत्पन्न हुई। धर्मदत्त के पास जो धन-सम्पत्ति थी, वह धीरे-धीरे व्यय होने लगी। एक बार किसी यात्रा में उनका व्यापारिक कारवाँ लुट गया। दूसरी बार अकाल पड़ा और उन्हें गाँववालों को अन्न दान करना पड़ा। तीसरी बार चोरों ने घर में सेंध लगा दी। इस प्रकार धर्मदत्त का धन क्षीण होता गया।\n\nधर्मदत्त अब पहले की तरह दान-पुण्य नहीं कर पाते थे। उनके घर में अन्न की कमी होने लगी। सुशीला चिन्तित होकर कहती —\n\n“स्वामी! अब हम क्या करें? घर में अन्न नहीं है, दान के लिए धन नहीं है। भगवान शिव ने हमें सन्तान दी, परन्तु अब हमारे सामने यह विपत्ति आई है।”\n\nधर्मदत्त ने धैर्य से कहा —\n\n“प्रिये! भगवान शिव की इच्छा के बिना कुछ नहीं होता। जब उन्होंने हमें पुत्र दिया, तो वे हमारा पेट भी भरेंगे। हमें अपना प्रदोष व्रत नहीं छोड़ना चाहिए।”\n\nशिवदत्त ने पिता की बात सुनी और कहा —\n\n“पिताजी! मैं अब बड़ा हो गया हूँ। मुझे कुछ कार्य करना चाहिए जिससे घर की स्थिति सुधरे। मैं वन में जाकर लकड़ी काटकर बेचूँगा।”\n\nधर्मदत्त ने कहा —\n\n“पुत्र! तुम ब्राह्मण हो। लकड़ी काटना तुम्हारा कार्य नहीं है।”\n\nशिवदत्त ने कहा —\n\n“पिताजी! भगवान शिव ने स्वयं शिवलिंग को धारण किया है। वे किसी कार्य को छोटा नहीं मानते। मैं परिश्रम करूँगा। भगवान शिव मेरी सहायता करेंगे।”\n\nइस प्रकार शिवदत्त प्रतिदिन वन में जाकर लकड़ी काटता और नगर में बेचता। परन्तु जो धन मिलता, वह केवल एक समय का भोजन ही जुटा पाता। सुमंगला भी घर में सिलाई-बुनाई का कार्य करके कुछ सहायता करती। परन्तु घर की स्थिति सुधरने का नाम नहीं ले रही थी।\n\nएक दिन सुमंगला ने अपने पति से कहा —\n\n“स्वामी! मेरे पिता ने मुझे कुछ आभूषण दिए थे। यदि आप आज्ञा दें, तो मैं उन्हें बेचकर कुछ धन ले आऊँ।”\n\nशिवदत्त ने कहा —\n\n“प्रिये! ये आभूषण तुम्हारे पिता का स्नेह हैं। इन्हें बेचना उचित नहीं। हमें धैर्य रखना चाहिए। भगवान शिव अवश्य कोई मार्ग दिखाएँगे।”\n\nउसी मास की त्रयोदशी निकट आई। शिवदत्त ने अपनी पत्नी से कहा —\n\n“सुमंगला! कल प्रदोष व्रत है। हमें विधिपूर्वक व्रत करना चाहिए। चाहे घर में अन्न न हो, परन्तु भगवान शिव का पूजन अवश्य करना चाहिए।”\n\nसुमंगला ने कहा —\n\n“स्वामी! घर में पूजन के लिए बेलपत्र और धतूरा भी नहीं हैं। मैं क्या करूँ?”\n\nशिवदत्त ने कहा —\n\n“प्रिये! भगवान शिव को फूलों की आवश्यकता नहीं, भक्ति की आवश्यकता है। मैं वन से बेलपत्र और धतूरा ले आऊँगा। तुम जल और दीपक की व्यवस्था करो।”\n\nशिवदत्त वन में गए। उन्होंने बेलपत्र, धतूरा और कुछ फूल चुने। लौटते समय उन्हें रास्ते में एक शिवलिंग दिखाई दिया, जो पुराना और जीर्ण-शीर्ण था। शिवदत्त ने उसे देखा और मन में कहा —\n\n“हे महादेव! यह आपका विग्रह जीर्ण है। मैं इसे साफ करके यहाँ भी आपका पूजन करूँगा।”\n\nउन्होंने अपने वस्त्र से शिवलिंग को साफ किया और उस पर जल अर्पित किया। फिर बेलपत्र चढ़ाए और हाथ जोड़कर प्रार्थना की —\n\n“ॐ नमः शिवाय। हे महादेव! मेरे परिवार की रक्षा करें। हमें इस कठिनाई से उबारें।”\n\nउसी क्षण आकाश में एक दिव्य प्रकाश फैल गया। भगवान शिव ने उन्हें दर्शन दिए और कहा —\n\n“शिवदत्त! तुम्हारी भक्ति से मैं प्रसन्न हूँ। तुम्हारे पिता धर्मदत्त ने प्रदोष व्रत से मुझे प्रसन्न किया। अब तुम भी उसी व्रत को कर रहे हो। मैं तुम्हें एक वरदान देता हूँ — जिस स्थान पर तुमने इस जीर्ण शिवलिंग का पूजन किया, वहाँ से कुछ ही दूर एक गुफा है। उस गुफा में एक पात्र रखा है, जिसमें मेरी कृपा से अन्न सदा भरा रहेगा। परन्तु यह पात्र तभी सदा भरा रहेगा जब तुम और तुम्हारी पत्नी प्रत्येक प्रदोष व्रत में इस शिवलिंग का पूजन करोगे।”\n\nशिवदत्त ने हाथ जोड़कर कहा —\n\n“महादेव! मैं यह व्रत सदा करूँगा। आपकी कृपा से ही मेरा परिवार चलेगा।”\n\nभगवान शिव अन्तर्धान हो गए। शिवदत्त ने गुफा में जाकर देखा — वहाँ एक चमकीला पात्र था, जिसमें अन्न भरा हुआ था। शिवदत्त ने उसे घर ले जाकर अपने माता-पिता को दिया। धर्मदत्त ने आश्चर्य से पूछा —\n\n“पुत्र! यह पात्र कहाँ से आया?”\n\nशिवदत्त ने सारी घटना सुनाई। धर्मदत्त ने भगवान शिव को प्रणाम किया और कहा —\n\n“हे महादेव! आपने हमें इस विपत्ति से उबारा। हम सदा आपके ऋणी रहेंगे।”\n\nउस दिन से प्रत्येक प्रदोष व्रत को शिवदत्त और सुमंगला उस जीर्ण शिवलिंग का पूजन करने लगे। वे वहाँ जल, बेलपत्र और धतूरा अर्पित करते। उस पात्र में अन्न कभी समाप्त नहीं हुआ। धीरे-धीरे शिवदत्त के परिवार की स्थिति सुधरने लगी। उन्होंने उस अन्न से दान-पुण्य भी आरम्भ किया।\n\nपरन्तु शिवदत्त की भक्ति की परीक्षा अभी समाप्त नहीं हुई थी। एक दिन उस नगर का राजा बीमार पड़ गया। वैद्यों ने बताया कि राजा का रोग केवल एक ही उपाय से ठीक हो सकता है — किसी निर्दोष ब्राह्मण कुमार का बलिदान। राजा ने अपने मंत्रियों को बुलाया —\n\n“मंत्री! यदि मैं ठीक होना चाहता हूँ, तो कोई ब्राह्मण कुमार चाहिए जो निर्दोष हो। उसे मेरी ओर से एक भेंट दी जाएगी और उसका बलिदान किया जाएगा।”\n\nमंत्रियों ने नगर में घोषणा करवाई। कोई भी अपने पुत्र को बलिदान के लिए तैयार नहीं था। परन्तु शिवदत्त ने यह सुना तो वह स्वयं राजा के पास पहुँचे और कहा —\n\n“महाराज! मैं निर्दोष ब्राह्मण कुमार हूँ। आप मेरा बलिदान कर सकते हैं।”\n\nराजा ने आश्चर्य से कहा —\n\n“पुत्र! तुम जानते हो कि तुम्हारा बलिदान होगा?”\n\nशिवदत्त ने कहा —\n\n“महाराज! मेरे पिता धर्मदत्त ने प्रदोष व्रत से मुझे पाया है। भगवान शिव की कृपा से मेरा पात्र सदा भरा रहता है। यदि मेरे बलिदान से आप ठीक हो जाएँ, तो यह मेरा सौभाग्य होगा।”\n\nराजा ने कहा —\n\n“पुत्र! तुमने मुझे आश्चर्य में डाल दिया। कोई अपने प्राण देने को तैयार नहीं होता।”\n\nशिवदत्त ने कहा —\n\n“महाराज! प्रदोष व्रत की महिमा से मैं निर्भय हूँ। भगवान शिव मेरी रक्षा करेंगे।”\n\nबलिदान का दिन आया। शिवदत्त को राज्यसभा में लाया गया। जब बलिदान की तैयारी हो रही थी, तब शिवदत्त ने मन में ‘ॐ नमः शिवाय’ का जप किया। उसी क्षण भगवान शिव प्रकट हुए और उन्होंने राजा से कहा —\n\n“राजन्! यह बालक मेरा परम भक्त है। इसने प्रदोष व्रत से मुझे प्रसन्न किया है। तुम इसका बलिदान नहीं कर सकते। तुम्हारा रोग इसलिए हुआ है क्योंकि तुमने पूर्व जन्म में एक ब्राह्मण का अपमान किया था। यदि तुम प्रदोष व्रत करो और ब्राह्मणों को दान दो, तो तुम्हारा रोग ठीक हो जाएगा।”\n\nराजा ने भगवान शिव के चरणों में प्रणाम किया और क्षमा माँगी। उसने प्रदोष व्रत करना आरम्भ किया और ब्राह्मणों को दान दिया। कुछ ही समय में उसका रोग ठीक हो गया।\n\nराजा ने शिवदत्त को बहुत धन दिया और उसे अपना मंत्री बनाया। शिवदत्त ने वह धन अपने परिवार और गाँव के कल्याण में लगाया। उसने उस जीर्ण शिवलिंग का जीर्णोद्धार करवाया और वहाँ एक सुन्दर मंदिर बनवाया।\n\nशिवदत्त और सुमंगला ने अपना प्रदोष व्रत कभी नहीं छोड़ा। उन्होंने अपने पुत्र को भी यह व्रत सिखाया। धर्मदत्त और सुशीला अपने पुत्र और पुत्रवधू की भक्ति देखकर धन्य हो गए।\n\nएक दिन भगवान शिव ने माँ पार्वती से कहा —\n\n“देवि! देखो, धर्मदत्त और शिवदत्त दोनों ने प्रदोष व्रत से मुझे प्रसन्न किया। एक ने सन्तान पाई, दूसरे ने धन और यश पाया। जो भी भक्त श्रद्धा से यह व्रत करता है, उसकी सभी मनोकामनाएँ पूर्ण होती हैं।”\n\nमाँ पार्वती ने कहा —\n\n“स्वामी! अब आप मुझे प्रदोष व्रत की सम्पूर्ण विधि, नियम और फल बताइए, जिससे मैं इसे सभी भक्तों तक पहुँचा सकूँ।”\n\nभगवान शिव ने कहा —\n\n“देवि! कल मैं तुम्हें प्रदोष व्रत का सम्पूर्ण महात्म्य बताऊँगा।”";

    $ch4Title = "प्रदोष व्रत का महात्म्य, विधि एवं फलश्रुति";
    $ch4Story = "अगले दिन कैलाश पर्वत पर भगवान शंकर अपनी प्रिय अर्धांगिनी माँ पार्वती के साथ विराजमान थे। सूर्यदेव अपनी स्वर्णिम किरणों से कैलाश की बर्फीली चोटियों को प्रकाशित कर रहे थे और नन्दी द्वार पर खड़े थे। माँ पार्वती ने हाथ जोड़कर पूछा —\n\n“स्वामी! आपने मुझे धर्मदत्त और शिवदत्त की कथा सुनाई। अब कृपया प्रदोष व्रत का सम्पूर्ण महात्म्य बताइए — इस व्रत का प्रादुर्भाव कैसे हुआ, इसकी विधि क्या है, किन नियमों का पालन करना चाहिए और इसका फल क्या है?”\n\nभगवान शिव ने मुस्कुराकर कहा —\n\n“देवि! तुमने अत्यन्त उत्तम प्रश्न पूछा है। सुनो, मैं तुम्हें प्रदोष व्रत का सम्पूर्ण महात्म्य विस्तार से बताता हूँ।”\n\nप्रदोष व्रत का प्रादुर्भाव\nभगवान शिव बोले —\n\n“देवि! जिस दिन समुद्र-मंथन से हलाहल विष प्रकट हुआ, उस दिन त्रयोदशी तिथि थी और सूर्यास्त का समय था। उस संधिकाल में — जब दिन और रात मिलते हैं — मैंने वह विष अपने कण्ठ में धारण किया। उस समय देवता और ऋषि-मुनि मेरी स्तुति कर रहे थे। उसी प्रदोष काल में मेरी पीड़ा शान्त हुई और मैंने देवताओं को आशीर्वाद दिया।\n\nउसी क्षण से यह काल मेरा प्रिय हो गया। जो भक्त इस काल में मेरी विधिपूर्वक पूजा करता है, उसके सारे कष्ट हर लिए जाते हैं। इसीलिए यह व्रत प्रदोष व्रत कहलाता है — क्योंकि यह उस काल में किया जाता है जब दिन और रात का मिलन होता है।”\n\nमाँ पार्वती ने पूछा —\n\n“स्वामी! प्रदोष व्रत कब-कब किया जाता है? क्या यह केवल त्रयोदशी को ही होता है?”\n\nभगवान शिव ने कहा —\n\n“देवि! प्रदोष व्रत प्रत्येक मास की शुक्ल त्रयोदशी और कृष्ण त्रयोदशी — दोनों को किया जाता है। इस प्रकार एक मास में दो प्रदोष व्रत होते हैं और एक वर्ष में चौबीस। परन्तु कुछ विशेष प्रदोष व्रत अत्यन्त फलदायी माने जाते हैं —\n\nशनि प्रदोष: जब त्रयोदशी शनिवार को पड़े।\nसोम प्रदोष: जब त्रयोदशी सोमवार को पड़े — यह सर्वश्रेष्ठ माना जाता है।\nरवि प्रदोष: जब त्रयोदशी रविवार को पड़े।\nमंगल प्रदोष: जब त्रयोदशी मंगलवार को पड़े।\nबुध प्रदोष: जब त्रयोदशी बुधवार को पड़े।\nगुरु प्रदोष: जब त्रयोदशी गुरुवार को पड़े।\nशुक्र प्रदोष: जब त्रयोदशी शुक्रवार को पड़े।\n\nइनमें से जो भी प्रदोष व्रत किसी विशेष वार को पड़े, उसका अपना विशेष महात्म्य है। परन्तु सामान्यतः प्रत्येक प्रदोष व्रत मेरी कृपा का द्वार है।”\n\nमाँ पार्वती ने पूछा —\n\n“स्वामी! प्रदोष व्रत की विधि क्या है? कृपया विस्तार से बताइए।”\n\nप्रदोष व्रत की विधि\nभगवान शिव ने कहा —\n\n“देवि! सुनो, प्रदोष व्रत की विधि इस प्रकार है —\n\n1. प्रातः स्नान एवं संकल्प: त्रयोदशी के दिन प्रातः ब्रह्ममुहूर्त में स्नान करके स्वच्छ वस्त्र पहनो। भगवान शिव के सम्मुख बैठकर हाथ में जल और अक्षत लेकर संकल्प करो —\n\n‘ॐ नमः शिवाय। मैं आज प्रदोष व्रत करूँगा/करूँगी। मेरी सभी मनोकामनाएँ पूर्ण हों। मेरे परिवार में सुख-शान्ति बनी रहे।’\n\n2. दिन का व्रत: दिनभर अन्न-जल ग्रहण न करें या फलाहार करें — दोनों विधियाँ शास्त्र-सम्मत हैं। परन्तु प्रदोष काल तक व्रत अवश्य रखें। अस्वस्थता में शास्त्र और चिकित्सक के परामर्श का पालन करें।\n\n3. प्रदोष काल का पूजन: सूर्यास्त के बाद, जब प्रदोष काल हो — लगभग डेढ़ घंटे तक — उस समय शिवलिंग का विधिवत पूजन करें। यह समय सर्वश्रेष्ठ है। पूजन में —\n\nअभिषेक: जल, दूध, दही, घी, शहद और शर्करा (पंचामृत) से शिवलिंग का अभिषेक करें।\nवस्त्र: शिवलिंग पर नया वस्त्र या कलावा अर्पित करें।\nचन्दन एवं रोली: चन्दन और रोली से तिलक करें।\nबेलपत्र: शिवलिंग पर बेलपत्र अवश्य चढ़ाएँ। बेलपत्र के बिना शिव-पूजन अधूरा माना जाता है।\nधतूरा: धतूरा और शमी पत्र अर्पित करें।\nपुष्प: कनेर के फूल, आक के फूल, गेंदा और अन्य पुष्प अर्पित करें।\nधूप-दीप: धूप और घी का दीपक जलाएँ।\nनैवेद्य: नारियल, केला, मिष्ठान, फल और गुड़ अर्पित करें।\nआरती: शिव-आरती और शिव-चालीसा का पाठ करें।\n\n4. कथा श्रवण: प्रदोष व्रत की कथा श्रद्धापूर्वक सुनें या पढ़ें।\n\n5. रात्रि जागरण: रात्रि में ‘ॐ नमः शिवाय’ का जप करें और जागरण करें। शिव-मंत्र का जप विशेष फलदायी है।\n\n6. पारण: अगले दिन प्रातः स्नान करके पारण करें। पारण में अन्न ग्रहण करें।”\n\nप्रदोष व्रत के नियम\nमाँ पार्वती ने पूछा —\n\n“स्वामी! इस व्रत में किन नियमों का पालन करना चाहिए?”\n\nभगवान शिव ने कहा —\n\n“देवि! सुनो —\n\nप्रदोष व्रत में सत्य बोलो, क्रोध मत करो, किसी की निन्दा मत करो।\nव्रत के दिन ब्रह्मचर्य का पालन करो।\nप्रदोष काल में पूजन अवश्य करो — यही व्रत का मुख्य अंग है।\nव्रत के दिन तामसिक भोजन (मांस, मदिरा, लहसुन, प्याज) ग्रहण मत करो।\nव्रत के दिन दान अवश्य करो — अन्न, वस्त्र या धन, जो भी सम्भव हो।\nव्रत का संकल्प एक बार लेने के बाद उसे पूर्ण करो। बीच में मत छोड़ो।\nयदि किसी कारण से कोई प्रदोष व्रत छूट जाए, तो अगले प्रदोष व्रत में दोनों की पूर्ति करो।\nव्रत के दिन शिवलिंग पर बेलपत्र अवश्य चढ़ाओ।\nप्रदोष काल में शिव-आरती और शिव-चालीसा का पाठ करो।”\n\nप्रदोष व्रत का फल\nमाँ पार्वती ने पूछा —\n\n“स्वामी! इस व्रत से कौन-कौन से फल प्राप्त होते हैं?”\n\nभगवान शिव ने कहा —\n\n“देवि! इस व्रत का फल अत्यन्त महान है। जो भक्त श्रद्धा और भक्ति से यह व्रत करता है —\nउसके सभी पाप नष्ट हो जाते हैं।\nउसके जीवन से सभी कष्ट दूर हो जाते हैं।\nरोग, शोक और दरिद्रता का नाश होता है।\nसन्तान-सुख की प्राप्ति होती है।\nविवाह में आने वाली बाधाएँ दूर होती हैं।\nधन-धान्य और समृद्धि की प्राप्ति होती है।\nशत्रुओं का नाश होता है।\nमनोकामनाएँ पूर्ण होती हैं।\nजो स्त्री यह व्रत करती है, उसका सौभाग्य अखण्ड रहता है।\nजो कन्या यह व्रत करती है, उसे मनोवांछित वर की प्राप्ति होती है।\nजो व्यापारी यह व्रत करता है, उसके व्यापार में वृद्धि होती है।\nजो विद्यार्थी यह व्रत करता है, उसकी बुद्धि तीव्र होती है।\nजो रोगी यह व्रत करता है, उसे रोग से मुक्ति मिलती है।\nजो सन्तानहीन यह व्रत करता है, उसे सन्तान की प्राप्ति होती है।\n\nपरन्तु देवि, सबसे बड़ा फल यह है कि जो प्रदोष व्रत करता है, उसे मेरी विशेष कृपा प्राप्त होती है। वह मेरे लोक को प्राप्त होता है और जन्म-मरण के बंधन से मुक्त हो जाता है।”\n\nसोम प्रदोष का विशेष महात्म्य\nमाँ पार्वती ने पूछा —\n\n“स्वामी! आपने कहा कि सोम प्रदोष सर्वश्रेष्ठ है। कृपया उसका विशेष महात्म्य बताइए।”\n\nभगवान शिव ने कहा —\n\n“देवि! जब त्रयोदशी सोमवार को पड़ती है, तो उसे सोम प्रदोष कहते हैं। सोमवार मेरा प्रिय दिन है और चन्द्रमा मेरे शीश पर विराजमान हैं। जो भक्त सोम प्रदोष का व्रत करता है, उसे अक्षय पुण्य की प्राप्ति होती है। उसकी सभी मनोकामनाएँ शीघ्र पूर्ण होती हैं।\n\nसोम प्रदोष के दिन चन्द्रमा की पूजा भी की जाती है। चन्द्रमा को जल और दूध अर्पित किया जाता है। इससे मन की शान्ति और मानसिक रोगों से मुक्ति मिलती है।”\n\nशनि प्रदोष का विशेष महात्म्य\nमाँ पार्वती ने पूछा —\n\n“स्वामी! शनि प्रदोष का क्या महात्म्य है?”\n\nभगवान शिव ने कहा —\n\n“देवि! जब त्रयोदशी शनिवार को पड़ती है, तो उसे शनि प्रदोष कहते हैं। शनिदेव कर्म के देवता हैं। जो भक्त शनि प्रदोष का व्रत करता है, उसे शनि की कृपा प्राप्त होती है। उसके कर्मों के बंधन ढीले होते हैं। शनि की महादशा में जो कष्ट होते हैं, वे इस व्रत से कम हो जाते हैं। शनि प्रदोष के दिन काले तिल, काली उड़द और लोहा दान करना विशेष फलदायी है।”\n\nभक्ति का महात्म्य\nमाँ पार्वती ने पूछा —\n\n“स्वामी! धर्मदत्त और शिवदत्त की कथा से क्या शिक्षा मिलती है?”\n\nभगवान शिव ने कहा —\n\n“देवि! इस कथा से यह शिक्षा मिलती है कि भगवान की कृपा से सब कुछ सम्भव है। धर्मदत्त को सन्तान नहीं थी, परन्तु प्रदोष व्रत से सन्तान मिली। शिवदत्त के घर में अन्न नहीं था, परन्तु प्रदोष व्रत से अन्न का पात्र मिला। शिवदत्त को मृत्यु के मुख से भगवान शिव ने बचाया। यह सब प्रदोष व्रत का ही चमत्कार था।\n\nइससे यह भी शिक्षा मिलती है कि भक्ति में विचलित नहीं होना चाहिए। धर्मदत्त ने विपत्ति में भी अपना व्रत नहीं छोड़ा। शिवदत्त ने अपने प्राणों का भी मोह नहीं किया। जो भक्त निष्काम भाव से भगवान की शरण में आता है, भगवान उसकी सदा रक्षा करते हैं।”\n\nफलश्रुति\nभगवान शिव ने कहा —\n\n“देवि! जो व्यक्ति इस प्रदोष व्रत कथा को श्रद्धापूर्वक सुनता है, वह इस व्रत का सम्पूर्ण फल प्राप्त करता है। जो स्त्री इस कथा को सुनकर प्रदोष व्रत करती है, उसका सुहाग अखण्ड रहता है। जो कन्या इस कथा को सुनती है, उसे योग्य वर मिलता है। जो पुरुष इस कथा को सुनता है, उसके सभी पाप नष्ट हो जाते हैं। जो सन्तानहीन इस कथा को सुनता है, उसे सन्तान की प्राप्ति होती है।\n\nजो इस कथा को पढ़ता या सुनाता है, उसे शिवलोक की प्राप्ति होती है। यह कथा जिस घर में सुनी जाती है, वहाँ सुख, समृद्धि और शान्ति बनी रहती है। जो इस कथा को प्रत्येक प्रदोष व्रत में सुनता है, उसकी सभी मनोकामनाएँ पूर्ण होती हैं।”\n\nइसके बाद भगवान शिव ने माँ पार्वती को आशीर्वाद दिया —\n\n“देवि! तुमने मेरी कथा को ध्यान से सुना। जो भक्त इस कथा को श्रद्धा से सुनेगा, उसे मेरी कृपा प्राप्त होगी।”\n\nमाँ पार्वती ने हाथ जोड़कर कहा —\n\n“ॐ नमः शिवाय। हे महादेव! आपकी कृपा से यह कथा सम्पूर्ण हुई। अब मैं सभी भक्तों को यह व्रत करने का आशीर्वाद देती हूँ कि जो भी इस व्रत को श्रद्धा से करेगा, उसके सभी कष्ट दूर होंगे और उसे शिवलोक की प्राप्ति होगी।”\n\nइति श्री प्रदोष व्रत कथा सम्पूर्णम्।\n\nॐ नमः शिवाय।\nॐ त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्।\nउर्वारुकमिव बन्धनान् मृत्योर्मुक्षीय माऽमृतात्॥";

