        'synopsis' => 'समुद्र-मंथन से हलाहल विष प्रकट होने पर भगवान शिव ने उसे अपने कण्ठ में धारण किया। उस प्रदोष काल में देवताओं ने उनकी स्तुति की। तभी से प्रदोष व्रत का प्रादुर्भाव हुआ। धर्मदत्त ने सन्तान-प्राप्ति के लिए और शिवदत्त ने अपनी रक्षा के लिए यह व्रत किया। दोनों को भगवान शिव की विशेष कृपा प्राप्त हुई।',
        'vrat_significance' => 'प्रदोष काल वह संधिकाल है जब दिन और रात मिलते हैं। इस काल में भगवान शिव की पूजा शीघ्र फल देती है। हलाहल विष पीकर शिव ने सृष्टि की रक्षा की, इसलिए यह व्रत शिव-कृपा का सर्वश्रेष्ठ साधन है।',
        'benefits' => 'पापों का नाश, कष्टों से मुक्ति, रोग-शोक-दरिद्रता का नाश, सन्तान-सुख, विवाह में बाधा दूर, धन-समृद्धि, शत्रुनाश, मनोकामना पूर्ण, सौभाग्य, मोक्ष की प्राप्ति।',
        'rules' => 'प्रातः स्नान कर संकल्प लें। दिनभर फलाहार या निराहार रहें। प्रदोष काल (सूर्यास्त के बाद 1.5 घंटे) में शिव-पूजन अवश्य करें। बेलपत्र, धतूरा, शमी पत्र अर्पित करें। रात्रि जागरण करें। अगले दिन पारण करें। तामसिक भोजन, क्रोध, निन्दा से बचें।',
        'opening_verse' => 'ॐ नमः शिवाय। कर्पूरगौरं करुणावतारं संसारसारं भुजगेन्द्रहारम्। सदावसन्तं हृदयारविन्दे भवं भवानीसहितं नमामि॥',
        'closing_verse' => 'ॐ त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्। उर्वारुकमिव बन्धनान् मृत्योर्मुक्षीय माऽमृतात्॥',
        'aarti_name' => 'ॐ जय शिव ओंकारा आरती',
        'samagri_list' => 'शिवलिंग, जल, दूध, दही, घी, शहद, शर्करा (पंचामृत), बेलपत्र, धतूरा, शमी पत्र, कुशा, कनेर के फूल, आक के फूल, गंगाजल, चन्दन, रोली, अक्षत, दीपक, घी, बाती, धूप, नारियल, फल, मिष्ठान, पुष्प-माला, आरती-पुस्तिका, शिव-चालीसा।',
        'vidhi' => json_encode($vidhiSteps, JSON_UNESCAPED_UNICODE),
        'katha_chapters' => json_encode($chaptersArray, JSON_UNESCAPED_UNICODE),
        'chapters' => json_encode($chaptersArray, JSON_UNESCAPED_UNICODE),
        'katha_text' => $kathaFullText,
        'translation_hi' => 'यह कथा बताती है कि प्रदोष काल में भगवान शिव की पूजा शीघ्र फल देती है। धर्मदत्त को सन्तान मिली और शिवदत्त की रक्षा हुई। जो भक्त श्रद्धा से यह व्रत करता है, उसके सभी कष्ट दूर होते हैं।',
        'translation_en' => 'This story teaches that worshipping Lord Shiva during Pradosh Kaal yields quick results. Dharmadatta received a son and Shivadatta was protected. One who observes this vow with devotion is freed from all troubles.',
        'translation_gu' => 'આ કથા શીખવે છે કે પ્રદોષ કાળમાં ભગવાન શિવની પૂજા ઝડપી ફળ આપે છે. ધર્મદત્તને સંતાન મળ્યું અને શિવદત્તની રક્ષા થઈ. જે ભક્ત શ્રદ્ધાથી આ વ્રત કરે છે, તેના બધા કષ્ટ દૂર થાય છે.',
        'translation_mr' => 'ही कथा सांगते की प्रदोष काळात भगवान शिवाची पूजा लवकर फळ देते. धर्मदत्ताला संतान मिळाले आणि शिवदत्ताचे रक्षण झाले. जो भक्त श्रद्धेने हे व्रत करतो, त्याचे सर्व कष्ट दूर होतात.',
        'is_featured' => 1
    ];

    $idsToUpsert = [
        'pradosh_vrat_katha',
        'katha_pradosh'
    ];

    $affected = 0;

    $sql = "INSERT INTO `vrat_katha` (
        `id`, `title`, `katha_name`, `sanskrit_title`, `sanskrit`, `category`, `category_label`,
        `deity`, `deity_name`, `duration`, `vrat_duration`, `vrat_day`, `vrat_month`, `tithi`,
        `synopsis`, `vrat_significance`, `benefits`, `rules`, `opening_verse`, `closing_verse`,
        `aarti_name`, `samagri_list`, `vidhi`, `katha_chapters`, `chapters`, `katha_text`,
        `translation_hi`, `translation_en`, `translation_gu`, `translation_mr`, `is_featured`
    ) VALUES (
        :id, :title, :katha_name, :sanskrit_title, :sanskrit, :category, :category_label,
        :deity, :deity_name, :duration, :vrat_duration, :vrat_day, :vrat_month, :tithi,
        :synopsis, :vrat_significance, :benefits, :rules, :opening_verse, :closing_verse,
        :aarti_name, :samagri_list, :vidhi, :katha_chapters, :chapters, :katha_text,
        :translation_hi, :translation_en, :translation_gu, :translation_mr, :is_featured
    ) ON DUPLICATE KEY UPDATE
        `title` = VALUES(`title`),
        `katha_name` = VALUES(`katha_name`),
        `sanskrit_title` = VALUES(`sanskrit_title`),
        `sanskrit` = VALUES(`sanskrit`),
        `category` = VALUES(`category`),
        `category_label` = VALUES(`category_label`),
        `deity` = VALUES(`deity`),
        `deity_name` = VALUES(`deity_name`),
        `duration` = VALUES(`duration`),
        `vrat_duration` = VALUES(`vrat_duration`),
        `vrat_day` = VALUES(`vrat_day`),
        `vrat_month` = VALUES(`vrat_month`),
        `tithi` = VALUES(`tithi`),
        `synopsis` = VALUES(`synopsis`),
        `vrat_significance` = VALUES(`vrat_significance`),
        `benefits` = VALUES(`benefits`),
        `rules` = VALUES(`rules`),
        `opening_verse` = VALUES(`opening_verse`),
        `closing_verse` = VALUES(`closing_verse`),
        `aarti_name` = VALUES(`aarti_name`),
        `samagri_list` = VALUES(`samagri_list`),
        `vidhi` = VALUES(`vidhi`),
        `katha_chapters` = VALUES(`katha_chapters`),
        `chapters` = VALUES(`chapters`),
        `katha_text` = VALUES(`katha_text`),
        `translation_hi` = VALUES(`translation_hi`),
        `translation_en` = VALUES(`translation_en`),
        `translation_gu` = VALUES(`translation_gu`),
        `translation_mr` = VALUES(`translation_mr`),
        `is_featured` = VALUES(`is_featured`)";

    $stmt = $db->prepare($sql);

    foreach ($idsToUpsert as $kId) {
        $params = array_merge($kathaData, [':id' => $kId]);
        $execParams = [];
        foreach ($params as $k => $v) {
            $key = str_starts_with($k, ':') ? $k : (':' . $k);
            $execParams[$key] = $v;
        }
        $stmt->execute($execParams);
        $affected++;
    }

    // Refresh vrat_kathas view
    try {
        $db->exec("CREATE OR REPLACE VIEW `vrat_kathas` AS SELECT * FROM `vrat_katha`");
    } catch (Exception $e) {}

    // Invalidate local filesystem caches
    $cacheDir = $webBackend . '/cache';
    if (is_dir($cacheDir)) {
        foreach (glob($cacheDir . '/*.json') as $cacheFile) {
            @unlink($cacheFile);
        }
    }

    $response = [
        "status" => "success",
        "message" => "Pradosh Vrat Katha successfully updated with all 4 comprehensive chapters in MySQL.",
        "upserted_ids" => $idsToUpsert,
        "total_chapters" => 4,
        "katha_text_length" => mb_strlen($kathaFullText, 'UTF-8'),
        "timestamp" => date('c')
    ];

    if ($isCli) {
        echo json_encode($response, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE) . "\n";
    } else {
        header("Content-Type: application/json; charset=UTF-8");
        echo json_encode($response, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);
    }

} catch (Throwable $e) {
    $errResp = [
        "status" => "error",
        "message" => $e->getMessage(),
        "trace" => $e->getTraceAsString()
    ];
    if ($isCli) {
        fwrite(STDERR, json_encode($errResp, JSON_PRETTY_PRINT) . "\n");
        exit(1);
    } else {
        header("Content-Type: application/json; charset=UTF-8");
        http_response_code(500);
        echo json_encode($errResp, JSON_PRETTY_PRINT);
    }
}
